/* Generated by stage0, the first SemanticScript compiler written in SemanticScript. Link it with the runtime of
   refined executables, semanticscript/compiler/refined/native_runtime.c, which writes output, traps, keeps
   regions, and runs the host library, as it does for `refined build --kind executable`. */
#include <stdbool.h>
#include <stdint.h>
#include <string.h>

void refined_start(int argc, char **argv);
void refined_trap(const char *p, int64_t n);
int32_t refined_write(int32_t fd, const char *p, int64_t n, int32_t newline);
int32_t refined_write_int(int32_t fd, int64_t v, int32_t newline);
void *refined_region_new(int64_t capacity, const char *label, int64_t label_len);
void *refined_region_alloc(void *handle, int64_t size);
void refined_region_free(void *handle);
void *refined_format_int(int64_t v, void *region, int64_t *out_len);
int64_t refined_find(const char *h, int64_t hn, const char *nd, int64_t nn);
int32_t refined_bytes_equal(const char *a, int64_t an, const char *b, int64_t bn);
int32_t refined_parse_int(const char *p, int64_t n, int64_t *out);
int32_t refined_host(const char *name, int64_t n, int64_t *args, int64_t *results, int64_t *payload);
void *refined_handle_region(int64_t h);

/* a call of the host library by a key written in place: `<target>|<slots per argument>|<result slots>` */
#define SS_HOST(key, a, o, e) refined_host((key), (int64_t)sizeof(key) - 1, (a), (o), (e))

/* text: a pointer and a length in bytes, as the LLVM backend's {i8*, i64} */
typedef struct { const char *p; int64_t n; } ss_string;
#define SS_TEXT(s) ((ss_string){ (s), (int64_t)(sizeof(s) - 1) })
#define SS_STATIC(s) { (s), (int64_t)(sizeof(s) - 1) }
typedef void ss_region;

static void ss_trap(const char *what) {
  refined_trap(what, (int64_t)strlen(what));
}

static bool ss_write(ss_string text) {
  return refined_write(1, text.p, text.n, 0) != 0;
}

static bool ss_write_line(ss_string text) {
  return refined_write(1, text.p, text.n, 1) != 0;
}

static bool ss_write_integer_line(int64_t value) {
  return refined_write_int(1, value, 1) != 0;
}

static bool ss_write_error(ss_string text) {
  return refined_write(2, text.p, text.n, 1) != 0;
}

static bool ss_is_letter(uint8_t v) {
  return (v >= 'a' && v <= 'z') || (v >= 'A' && v <= 'Z');
}

static bool ss_is_digit(uint8_t v) {
  return v >= '0' && v <= '9';
}

static bool ss_is_letter_or_digit(uint8_t v) {
  return ss_is_letter(v) || ss_is_digit(v);
}

static bool ss_is_space(uint8_t v) {
  return v == 32 || v == 9 || v == 10 || v == 13;
}

static bool ss_is_punctuation(uint8_t v) {
  return (v >= 33 && v <= 47) || (v >= 58 && v <= 64) || (v >= 91 && v <= 96) || (v >= 123 && v <= 126);
}

static int64_t ss_add(int64_t left, int64_t right) {
  int64_t out;
  if (__builtin_add_overflow(left, right, &out)) ss_trap("math.addInt64 overflowed Int64");
  return out;
}

static int64_t ss_subtract(int64_t left, int64_t right) {
  int64_t out;
  if (__builtin_sub_overflow(left, right, &out)) ss_trap("math.subtractInt64 overflowed Int64");
  return out;
}

static int64_t ss_multiply(int64_t left, int64_t right) {
  int64_t out;
  if (__builtin_mul_overflow(left, right, &out)) ss_trap("math.multiplyInt64 overflowed Int64");
  return out;
}

static int64_t ss_divide(int64_t left, int64_t right) {
  if (right == 0) ss_trap("math.divideInt64 divided by zero");
  if (left == INT64_MIN && right == -1) ss_trap("math.divideInt64 overflowed Int64");
  return left / right;
}

static int64_t ss_remainder(int64_t left, int64_t right) {
  if (right == 0) ss_trap("math.remainderInt64 divided by zero");
  if (left == INT64_MIN && right == -1) ss_trap("math.remainderInt64 overflowed Int64");
  return left % right;
}

static int64_t ss_negate(int64_t value) {
  if (value == INT64_MIN) ss_trap("math.negateInt64 overflowed Int64");
  return -value;
}

static int64_t ss_absolute(int64_t value) {
  if (value == INT64_MIN) ss_trap("math.absoluteInt64 overflowed Int64");
  return value < 0 ? -value : value;
}

/* square and multiply, as the LLVM backend: an overflowing square happens only while exponent bits remain */
static int64_t ss_power(int64_t base, int64_t exponent) {
  int64_t result = 1;
  if (exponent < 0) ss_trap("math.powerInt64 with a negative exponent");
  while (exponent > 0) {
    if (exponent & 1) {
      if (__builtin_mul_overflow(result, base, &result)) ss_trap("math.powerInt64 overflowed Int64");
    }
    exponent >>= 1;
    if (exponent > 0 && __builtin_mul_overflow(base, base, &base)) ss_trap("math.powerInt64 overflowed Int64");
  }
  return result;
}

static int ss_exit_code(int64_t value) {
  if (value < 0 || value > 255) ss_trap("convert.int64ToExitCode was given a value outside 0 to 255");
  return (int)value;
}

static uint8_t ss_to_byte(int64_t value) {
  if (value < 0 || value > 255) ss_trap("convert.int64ToByte was given a value outside 0 to 255");
  return (uint8_t)value;
}

static void ss_pass(int64_t *passes, int64_t bound, const char *label) {
  *passes += 1;
  if (*passes > bound) ss_trap("a loop returned to its header more often than its maxIterations");
  (void)label;
}

static void ss_deeper(int64_t *depth, int64_t bound, const char *name) {
  *depth += 1;
  if (*depth > bound) ss_trap("an operation called itself deeper than its maxRecursion");
  (void)name;
}

/* regions are the runtime's: every allocation is counted against maxBytes as the LLVM backend counts it */
static ss_region *ss_region_new(int64_t capacity, const char *label) {
  return refined_region_new(capacity, label, (int64_t)strlen(label));
}

static void *ss_alloc(ss_region *r, int64_t size) {
  return refined_region_alloc(r, size);
}

static void ss_region_free(ss_region *r) {
  refined_region_free(r);
}

/* text */
static ss_string ss_relocate(ss_string text, ss_region *r) {
  char *p = ss_alloc(r, text.n);
  if (text.n) memcpy(p, text.p, (size_t)text.n);
  return (ss_string){ p, text.n };
}

static ss_string ss_concat(ss_string left, ss_string right, ss_region *r) {
  char *p = ss_alloc(r, left.n + right.n);
  if (left.n) memcpy(p, left.p, (size_t)left.n);
  if (right.n) memcpy(p + left.n, right.p, (size_t)right.n);
  return (ss_string){ p, left.n + right.n };
}

static ss_string ss_from_int64(int64_t value, ss_region *r) {
  int64_t n = 0;
  const char *p = refined_format_int(value, r, &n);
  return (ss_string){ p, n };
}

static bool ss_equals(ss_string left, ss_string right) {
  return refined_bytes_equal(left.p, left.n, right.p, right.n) != 0;
}

static bool ss_starts_with(ss_string text, ss_string prefix) {
  return text.n >= prefix.n && refined_bytes_equal(text.p, prefix.n, prefix.p, prefix.n) != 0;
}

static bool ss_to_int64(int64_t *out, ss_string text) {
  return refined_parse_int(text.p, text.n, out) != 0;
}

static ss_string ss_to_bytes(ss_string text) {
  return text;
}

static int64_t ss_byte_length(ss_string text) {
  return text.n;
}

static bool ss_splits(ss_string text, int64_t at) {
  return at >= 0 && at < text.n && ((unsigned char)text.p[at] & 0xC0) == 0x80;
}

/* string.slice: a view of whole characters inside the text, or the failure flag */
static bool ss_slice(ss_string *out, ss_string text, int64_t start, int64_t length) {
  if (start < 0 || length < 0 || start > text.n || length > text.n - start) return true;
  if (ss_splits(text, start) || ss_splits(text, start + length)) return true;
  *out = (ss_string){ text.p + start, length };
  return false;
}

static bool ss_byte_at(uint8_t *out, ss_string text, int64_t index) {
  if (index < 0 || index >= text.n) return true;
  *out = (uint8_t)text.p[index];
  return false;
}

static uint8_t ss_byte_at_or_trap(ss_string text, int64_t index) {
  if (index < 0 || index >= text.n) ss_trap("string.byteAtOrTrap read a byte outside its text");
  return (uint8_t)text.p[index];
}

/* string.advancePosition (D-71): the position after the character at a position's offset. A character is the
   UTF-8 sequence its lead byte announces when that many continuation bytes follow; any other byte is one of its
   own. A newline moves to column 1 of the next line, anything else one column right; an offset outside the text
   fails. string.Position is the program's first declared type, so this is a macro over its fields. */
#define ss_advance_position(out, text, pos) \
  ss_advance(&(out)->m_offset, &(out)->m_line, &(out)->m_column, (text), (pos).m_offset, (pos).m_line, (pos).m_column)

static bool ss_follows(ss_string text, int64_t at) {
  return at < text.n && ((unsigned char)text.p[at] & 0xC0) == 0x80;
}

static bool ss_advance(int64_t *offset, int64_t *line, int64_t *column, ss_string text, int64_t o, int64_t l,
                       int64_t c) {
  if (o < 0 || o >= text.n) return true;
  unsigned char lead = (unsigned char)text.p[o];
  int64_t want = (lead >= 0xF0 && lead <= 0xF4) ? 4 : (lead >= 0xE0 && lead <= 0xEF) ? 3 :
                 (lead >= 0xC2 && lead <= 0xDF) ? 2 : 1;
  bool whole = true;
  for (int64_t k = 1; k <= 3; k++) {
    if (want > k && !ss_follows(text, o + k)) whole = false;
  }
  int64_t width = whole ? want : 1;
  int64_t next_line = l, next_column = c;
  if (lead == 10) {
    if (__builtin_add_overflow(l, 1, &next_line)) ss_trap("string.advancePosition overflowed Int64");
    next_column = 1;
  } else {
    if (__builtin_add_overflow(c, 1, &next_column)) ss_trap("string.advancePosition overflowed Int64");
  }
  if (offset) *offset = o + width;
  if (line) *line = next_line;
  if (column) *column = next_column;
  return false;
}

static bool ss_find(int64_t *out, ss_string text, ss_string needle) {
  int64_t at = refined_find(text.p, text.n, needle.p, needle.n);
  if (at < 0) return true;
  *out = at;
  return false;
}

/* lists: a header {length, capacity, data, region, identity} in the list's region, as the LLVM backend's, and a
   data block that starts at four items and doubles */
typedef struct { int64_t length, capacity; void *data; ss_region *region; int64_t identity; } ss_list;
static int64_t ss_lists;

static ss_list *ss_list_new(ss_region *r) {
  ss_list *list = ss_alloc(r, (int64_t)sizeof(ss_list));
  memset(list, 0, sizeof(ss_list));
  list->region = r;
  ss_lists += 1;
  list->identity = ss_lists;
  return list;
}

static void *ss_list_slot(ss_list *list, int64_t size) {
  if (list->length == list->capacity) {
    int64_t capacity = list->capacity == 0 ? 4 : list->capacity * 2;
    char *fresh = ss_alloc(list->region, capacity * size);
    if (list->length) memcpy(fresh, list->data, (size_t)(list->length * size));
    list->data = fresh;
    list->capacity = capacity;
  }
  list->length += 1;
  return (char *)list->data + (list->length - 1) * size;
}

static bool ss_list_outside(ss_list *list, int64_t index) {
  return index < 0 || index >= list->length;
}

static void ss_list_trap(void) {
  ss_trap("a list was read at a position outside it");
}

